# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::OutboxDelivery do
  def outbox_delivery_outcome(state)
    Invoices::ReservationOutcome.new(state:, conflicts: [], counts: {})
  end

  def outbox_delivery_settled_adapter(state)
    outcome = outbox_delivery_outcome(state)
    RecordingReservationAdapter.new(prepare: outcome, commit: outcome, abort: outcome)
  end

  # "It builds the request from the stored outbox row and intent (company_id, invoice_id, operation_id, generation, disposition, desired_entry_ids), never from the invoice's current lines."
  # The intent is looked up under the outbox row's own company, so a row can never settle another company's reservation.
  it "sends nothing when the only intent matching the outbox row's operation belongs to another company" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 202, invoice_id: 10, operation_id:, state: "committed", generation: 1,
      disposition: "active", desired_entry_ids: [1, 2]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id: 101, invoice_id: 10, operation_id:, kind: "commit",
      payload: { company_id: 202, invoice_id: 10, operation_id:, generation: 1, disposition: "active", desired_entry_ids: [1, 2] }
    )
    adapter = outbox_delivery_settled_adapter("committed")

    described_class.new(adapter_source: -> { adapter }).deliver(item.id)

    expect(adapter.requests).to be_empty
    expect(item.reload.delivered_at).to be_nil
  end

  # "It builds the request from the stored outbox row and intent (company_id, invoice_id, operation_id, generation, disposition, desired_entry_ids), never from the invoice's current lines."
  # "an undelivered commit row is delivered once and a second delivery changes nothing"
  # One row's invoice changed after the save and the other row's invoice id names
  # no invoice at all: both requests must come from the stored row and intent,
  # with the intent's entries sent sorted.
  it "delivers each undelivered commit row once from its stored intent and a second delivery changes nothing" do
    invoice = create(:invoice)
    missing_invoice_id = 99_999
    changed_operation_id = SecureRandom.uuid
    missing_operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: changed_operation_id, state: "committed",
      generation: 7, disposition: "retained", desired_entry_ids: [12, 11]
    )
    InvoiceOperationIntent.create!(
      company_id: invoice.company_id, invoice_id: missing_invoice_id, operation_id: missing_operation_id,
      state: "committed", generation: 3, disposition: "active", desired_entry_ids: [5, 4]
    )
    rows = [
      [invoice.id, changed_operation_id, 7, "retained", [11, 12]],
      [missing_invoice_id, missing_operation_id, 3, "active", [4, 5]]
    ].map do |invoice_id, operation_id, generation, disposition, entry_ids|
      InvoiceOperationOutboxItem.create!(
        company_id: invoice.company_id, invoice_id:, operation_id:, kind: "commit",
        payload: {
          "company_id" => invoice.company_id, "invoice_id" => invoice_id, "operation_id" => operation_id,
          "generation" => generation, "disposition" => disposition, "desired_entry_ids" => entry_ids
        }
      )
    end
    invoice.update_column(:reference, "changed-after-save")
    received = []
    adapter = RecordingReservationAdapter.new(
      prepare: outbox_delivery_outcome("prepared"),
      commit: ->(request) { received << request; outbox_delivery_outcome("committed") },
      abort: outbox_delivery_outcome("aborted")
    )
    delivery = described_class.new(adapter_source: -> { adapter })

    rows.each { |row| delivery.deliver(row.id) }
    first_states = rows.map { |row| row.reload.attributes }
    rows.each { |row| delivery.deliver(row.id) }

    expect(Invoice.exists?(missing_invoice_id)).to be(false)
    expect(received.size).to eq(2)
    expect(received.first).to have_attributes(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: changed_operation_id,
      generation: 7, disposition: "retained", entries: [11, 12]
    )
    expect(received.second).to have_attributes(
      company_id: invoice.company_id, invoice_id: missing_invoice_id, operation_id: missing_operation_id,
      generation: 3, disposition: "active", entries: [4, 5]
    )
    expect(first_states.pluck("delivered_at")).to all(be_present)
    expect(rows.map { |row| row.reload.attributes }).to eq(first_states)
    [changed_operation_id, missing_operation_id].each do |operation_id|
      expect(InvoiceOperationOutboxItem.where(company_id: invoice.company_id, operation_id:).count).to eq(1)
    end
  end

  # "It calls the adapter's `commit` or `abort`, sets `delivered_at` only on a settled outcome, and otherwise keeps the row and increments `attempts`."
  it "keeps a row undelivered and counts an attempt when the adapter answers retryable or raises" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 1, invoice_id: 10, operation_id:, state: "failed",
      generation: 1, disposition: "active", desired_entry_ids: [5]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id: 1, invoice_id: 10, operation_id:, kind: "abort",
      payload: {
        "company_id" => 1, "invoice_id" => 10, "operation_id" => operation_id,
        "generation" => 1, "disposition" => "active", "desired_entry_ids" => [5]
      }
    )
    retryable_adapter = RecordingReservationAdapter.new(
      prepare: outbox_delivery_outcome("prepared"),
      commit: outbox_delivery_outcome("committed"),
      abort: outbox_delivery_outcome("retryable")
    )
    raising_adapter = RecordingReservationAdapter.new(
      prepare: outbox_delivery_outcome("prepared"),
      commit: outbox_delivery_outcome("committed"),
      abort: ->(_request) { raise "reservation store unreachable" }
    )

    described_class.new(adapter_source: -> { retryable_adapter }).deliver(row.id)
    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)

    expect { described_class.new(adapter_source: -> { raising_adapter }).deliver(row.id) }.not_to raise_error
    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(2)
  end

  # "It builds the request from the stored outbox row and intent (company_id, invoice_id, operation_id, generation, disposition, desired_entry_ids), never from the invoice's current lines."
  it "builds the request from the row's own company when two companies share an operation id" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.insert_all!([
      { company_id: 1, invoice_id: 10, operation_id:, state: "committed", generation: 3,
        desired_entry_ids: [1, 2], disposition: "active", created_at: Time.current },
      { company_id: 2, invoice_id: 10, operation_id:, state: "committed", generation: 3,
        desired_entry_ids: [7, 8], disposition: "retained", created_at: Time.current }
    ])
    item = InvoiceOperationOutboxItem.create!(
      company_id: 2, invoice_id: 10, operation_id:, kind: "commit",
      payload: { "company_id" => 2, "invoice_id" => 10, "operation_id" => operation_id }
    )
    adapter = outbox_delivery_settled_adapter("committed")

    described_class.new(adapter_source: -> { adapter }).deliver(item.id)

    expect(adapter.requests.size).to eq(1)
    request = adapter.requests.first
    expect(request.company_id).to eq(2)
    expect(request.entries).to eq([7, 8])
    expect(request.disposition).to eq("retained")
    expect(InvoiceOperationOutboxItem.where(company_id: 1).count).to eq(0)
    expect(item.reload.delivered_at).to be_present
  end

  it "delivers an abort row through abort when its invoice no longer exists" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 7301, invoice_id: 9301, operation_id:, state: "failed", generation: 2,
      disposition: "active", desired_entry_ids: [31, 32]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id: 7301, invoice_id: 9301, operation_id:, kind: "abort",
      payload: { company_id: 7301, invoice_id: 9301, operation_id:, generation: 2, disposition: "active", desired_entry_ids: [31, 32] }
    )
    aborts = []
    adapter = RecordingReservationAdapter.new(
      prepare: outbox_delivery_outcome("prepared"),
      commit: outbox_delivery_outcome("committed"),
      abort: ->(request) { aborts << request; outbox_delivery_outcome("aborted") }
    )

    described_class.new(adapter_source: -> { adapter }).deliver(item.id)

    expect(Invoice.exists?(9301)).to be(false)
    expect(aborts.map(&:entries)).to eq([[31, 32]])
    expect(item.reload.delivered_at).to be_present
    expect(item.attempts).to eq(0)
  end

  context "when another deliverer holds the row", committed_data: true do
    it "returns without calling the adapter and leaves the row unchanged" do
      operation_id = SecureRandom.uuid
      InvoiceOperationIntent.create!(
        company_id: 7401, invoice_id: 9401, operation_id:, state: "committed", generation: 1,
        disposition: "active", desired_entry_ids: [41]
      )
      item = InvoiceOperationOutboxItem.create!(
        company_id: 7401, invoice_id: 9401, operation_id:, kind: "commit",
        payload: { company_id: 7401, invoice_id: 9401, operation_id:, generation: 1, disposition: "active", desired_entry_ids: [41] }
      )
      adapter = outbox_delivery_settled_adapter("committed")
      locked = Queue.new
      release = Queue.new
      holder = committed_data_thread do
        InvoiceOperationOutboxItem.transaction do
          InvoiceOperationOutboxItem.lock("FOR UPDATE").find(item.id)
          locked << true
          release.pop
        end
      end
      locked.pop(timeout: 5)

      result = described_class.new(adapter_source: -> { adapter }).deliver(item.id)
      release << true
      holder.join(5)

      expect(result).to be_nil
      expect(adapter.requests).to be_empty
      expect(item.reload.attributes.slice("delivered_at", "attempts")).to eq("delivered_at" => nil, "attempts" => 0)
    ensure
      release&.push(true)
      holder&.join(5)
    end
  end

  it "reports a failed write of the delivery result instead of raising, and leaves the row undelivered" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 7501, invoice_id: 9501, operation_id:, state: "failed", generation: 1,
      disposition: "active", desired_entry_ids: [51]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id: 7501, invoice_id: 9501, operation_id:, kind: "abort",
      payload: { company_id: 7501, invoice_id: 9501, operation_id:, generation: 1, disposition: "active", desired_entry_ids: [51] }
    )
    adapter = outbox_delivery_settled_adapter("aborted")
    delivery = described_class.new(adapter_source: -> { adapter })
    allow(delivery).to receive(:record).and_raise(ActiveRecord::StatementInvalid, "result write failed")

    expect { expect(delivery.deliver(item.id)).to be_nil }.not_to raise_error
    expect(item.reload.delivered_at).to be_nil
  end
end

RSpec.describe Invoices::OutboxDelivery do
  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) { example.run }
  end

  # Returns every undeliverable-operation event sent while the block runs, with symbol keys.
  def undeliverable_security_event_payloads
    events = []
    subscriber = Object.new
    subscriber.define_singleton_method(:emit) { |event| events << event }
    Rails.event.subscribe(subscriber)
    begin
      yield
    ensure
      Rails.event.unsubscribe(subscriber)
    end
    events.filter_map do |event|
      event[:payload].to_h.symbolize_keys if event[:name] == Invoices::UndeliverableOperation::NAME
    end
  end

  it "a stale_generation commit answer emits one undeliverable event carrying only company_id, operation_id and kind, with no token and no body" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    entry_id = fake.add_entry(company_id:, user_id:, project_id: fake.add_project(company_id:))["id"]
    client = Timekeeping::ReservationClient.new(http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil))

    operation_id = SecureRandom.uuid
    # The stored generation is older than the fake's, so the fake answers 409 stale_generation.
    stale_generation = fake.generation - 1
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 501, operation_id:, state: "committed", generation: stale_generation,
      disposition: "active", desired_entry_ids: [entry_id]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 501, operation_id:, kind: "commit",
      payload: { company_id:, invoice_id: 501, operation_id:, generation: stale_generation, disposition: "active",
                 desired_entry_ids: [entry_id] }
    )

    payloads = undeliverable_security_event_payloads do
      described_class.new(adapter_source: -> { client }).deliver(item.id)
    end

    # "When the adapter answers retryable with reason `stale_generation`, set `undeliverable_at` and emit `Invoices::UndeliverableOperation.notify(company_id:, operation_id:, kind:)`."
    expect(item.reload.undeliverable_at).not_to be_nil
    expect(item.delivered_at).to be_nil
    expect(payloads.size).to eq(1)
    # "The payload carries no token and no body."
    expect(payloads.first.keys).to contain_exactly(:company_id, :operation_id, :kind)
    expect(payloads.first).to eq(company_id:, operation_id:, kind: "commit")

    sent_tokens = fake.requests.filter_map { |request| TimekeepingContract::Wire.bearer(request[:headers]) }
    expect(sent_tokens).not_to be_empty
    rendered = payloads.first.values.map(&:to_s)
    sent_tokens.each { |token| expect(rendered).not_to include(token) }
    expect(rendered).not_to include(entry_id.to_s)
  end
end

# Committed data, so the event is proven to fire when the mark really commits.
RSpec.describe Invoices::OutboxDelivery, committed_data: true do
  # "a stale_generation answer sets `undeliverable_at`, keeps the row and emits one event, and a later recovery run sends no request for that row."
  # "When the adapter answers retryable with reason `stale_generation`, set `undeliverable_at` and emit `Invoices::UndeliverableOperation.notify(company_id:, operation_id:, kind:)`."
  it "marks a stale_generation commit row undeliverable once, keeps the row and its payload, emits one event and sends nothing on a second delivery" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.generation = 7
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:)["id"]
    invoice_id = 88_101
    operation_id = SecureRandom.uuid
    payload = {
      "company_id" => company_id, "invoice_id" => invoice_id, "operation_id" => operation_id,
      "generation" => 7, "disposition" => "active", "desired_entry_ids" => [entry_id]
    }
    InvoiceOperationIntent.create!(
      company_id:, invoice_id:, operation_id:, state: "committed", generation: 7,
      disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(company_id:, invoice_id:, operation_id:, kind: "commit", payload:)
    events = []
    subscriber = Object.new
    subscriber.define_singleton_method(:emit) { |event| events << event }
    first_state = nil
    requests_after_first = nil
    requests_after_second = nil

    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) do
      client = Timekeeping::ReservationClient.new(http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil))
      request = Invoices::ReservationRequest.new(
        company_id:, invoice_id:, operation_id:, generation: 7, disposition: "active", entries: [entry_id]
      )
      expect(client.prepare(request).state).to eq("prepared")
      # The service moved to a newer generation, so it answers the stored row's commit with 409 stale_generation.
      fake.generation = 8
      delivery = described_class.new(adapter_source: -> { client })

      Rails.event.subscribe(subscriber)
      begin
        delivery.deliver(row.id)
        first_state = row.reload.attributes
        requests_after_first = fake.requests.size
        delivery.deliver(row.id)
        requests_after_second = fake.requests.size
      ensure
        Rails.event.unsubscribe(subscriber)
      end
    end

    expect(InvoiceOperationOutboxItem.exists?(row.id)).to be(true)
    expect(first_state["undeliverable_at"]).to be_present
    expect(first_state["delivered_at"]).to be_nil
    expect(first_state["payload"]).to eq(payload)
    # A second reach of the row must change nothing: same timestamp, no request, no second event.
    expect(row.reload.attributes).to eq(first_state)
    expect(requests_after_second).to eq(requests_after_first)

    undeliverable = events.select { |event| event[:name] == "invoices.undeliverable_operation" }
    expect(undeliverable.size).to eq(1)
    # "The payload carries no token and no body."
    expect(undeliverable.first[:payload].to_h.symbolize_keys).to eq(company_id:, operation_id:, kind: "commit")
  end
end

RSpec.describe Invoices::OutboxDelivery do
  # "with the Timekeeping client, a commit row answered committed while the stored intent is failed stays undelivered with attempts + 1"
  # "remote committed with intent committed → existing_success; remote aborted with intent failed → save_failed; any other pair → retryable reconciliation_error. HTTP 200 alone is never success."
  it "with the Timekeeping client a commit row answered committed while the stored intent is failed stays undelivered with one more attempt" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.generation = 7
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:)["id"]
    invoice_id = 88_201
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id:, invoice_id:, operation_id:, state: "failed", generation: 7,
      disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id:, operation_id:, kind: "commit",
      payload: {
        "company_id" => company_id, "invoice_id" => invoice_id, "operation_id" => operation_id,
        "generation" => 7, "disposition" => "active", "desired_entry_ids" => [entry_id]
      }
    )

    outcome = nil
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) do
      client = Timekeeping::ReservationClient.new(http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil))
      request = Invoices::ReservationRequest.new(
        company_id:, invoice_id:, operation_id:, generation: 7, disposition: "active", entries: [entry_id]
      )
      expect(client.prepare(request).state).to eq("prepared")

      outcome = described_class.new(adapter_source: -> { client }).deliver(row.id)
    end

    # The remote side really committed, so only the intent state can hold the row back.
    expect(outcome&.state).to eq("committed")
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => invoice_id, "state" => "committed" }])
    row.reload
    expect(row.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
  end
end

